#pragma once
#include "kstationFlashStateTask.h"
#include <cstdint>
namespace kstation {
class SustainReleaseTask final {
public:
 enum class Stage:uint8_t{WritePart,ReadPart,ClearIndex,WriteIndex,ReadCount,SaveCount,SavePart,LookupVoice,ReadAge,SelectAge,ReadOwner,CompareOwner,SelectOwner,ReadDeferred,SelectDeferred,ClearDeferred,WriteDeferred,MaskAge,MarkAge,CopyAge,BindSentinel,WriteAge,ReadPatch,SelectDsp,Gate,ReadIndex,IncrementIndex,WriteNextIndex,RestorePart,RestoreCount,DecrementCount,Repeat,Return,AwaitChild,Complete};
 enum class Child:uint8_t{None,Voice,Dsp,Gate};enum class Read:uint8_t{Part,Count,Age,Owner,Deferred,Patch,Index};enum class Write:uint8_t{Part,Index,Deferred,Age};
 explicit SustainReleaseTask(uint8_t part):part_(part){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}Child child()const{return stage_==Stage::AwaitChild?child_:Child::None;}uint32_t voice()const{return voice_;}bool resume(Child c,uint32_t value=0){if(child()!=c||c==Child::None)return false;if(c==Child::Voice)voice_=value;stage_=next_;child_=Child::None;return true;}
 unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::WritePart:case Stage::WriteIndex:case Stage::WriteNextIndex:return 9+c.write;case Stage::ReadPart:case Stage::ReadCount:case Stage::ReadIndex:return 9+c.read;case Stage::ReadAge:case Stage::ReadOwner:case Stage::ReadDeferred:return 12+c.read;case Stage::WriteDeferred:return 12+c.write;case Stage::ReadPatch:return 15+c.read;case Stage::WriteAge:return 15+c.write;case Stage::SaveCount:case Stage::SavePart:return c.pushWord;case Stage::RestorePart:case Stage::RestoreCount:return c.popWord;case Stage::LookupVoice:case Stage::SelectDsp:case Stage::Gate:return c.call;case Stage::BindSentinel:return 6;case Stage::Return:return c.ret;case Stage::AwaitChild:case Stage::Complete:return 0;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned available,const FlashCredits&c,R&&r,W&&w){auto cost=nextClocks(c);if(!cost||cost>available)return 0;auto n=Stage(unsigned(stage_)+1);switch(stage_){case Stage::WritePart:w(Write::Part,part_);break;case Stage::ReadPart:part_=uint8_t(r(Read::Part));break;case Stage::ClearIndex:index_=0;break;case Stage::WriteIndex:case Stage::WriteNextIndex:w(Write::Index,index_);break;case Stage::ReadCount:remaining_=uint8_t(r(Read::Count));break;case Stage::LookupVoice:request(Child::Voice,Stage::ReadAge);return cost;case Stage::ReadAge:age_=uint16_t(r(Read::Age));break;case Stage::SelectAge:if(!age_)n=Stage::ReadIndex;break;case Stage::ReadOwner:owner_=uint8_t(r(Read::Owner));break;case Stage::SelectOwner:if(owner_!=part_)n=Stage::ReadIndex;break;case Stage::ReadDeferred:deferred_=uint8_t(r(Read::Deferred));break;case Stage::SelectDeferred:if(!deferred_)n=Stage::ReadIndex;break;case Stage::WriteDeferred:w(Write::Deferred,0);break;case Stage::MaskAge:age_&=0x3fff;break;case Stage::MarkAge:age_|=1;break;case Stage::WriteAge:w(Write::Age,(uint32_t(age_)<<16)|0xffff);break;case Stage::ReadPatch:r(Read::Patch);break;case Stage::SelectDsp:request(Child::Dsp,Stage::Gate);return cost;case Stage::Gate:request(Child::Gate,Stage::ReadIndex);return cost;case Stage::ReadIndex:index_=uint8_t(r(Read::Index));break;case Stage::IncrementIndex:++index_;break;case Stage::DecrementCount:--remaining_;break;case Stage::Repeat:if(remaining_)n=Stage::SaveCount;break;case Stage::Return:n=Stage::Complete;break;default:break;}stage_=n;return cost;}
private:void request(Child c,Stage n){child_=c;next_=n;stage_=Stage::AwaitChild;}Stage stage_=Stage::WritePart,next_=Stage::Complete;Child child_=Child::None;uint32_t voice_=0;uint16_t age_=0;uint8_t part_=0,index_=0,remaining_=0,owner_=0,deferred_=0;
};
}
